  readingPassages.forEach(p => p.qs.forEach((q, i) => add(`reading-g7-exp-${p.code}-${i + 1}`, "reading", p.domain, q[2], q[0] === "low" ? "Low" : q[0] === "med" ? "Medium" : q[0] === "high" ? "High" : "Advanced", q[1], "Composite Passage Reasoning", p.stimulus, q[3], q[4], 0, q[5], q[0] === "adv")));
